"""Create reproducible EDA notebooks (outputs are generated by execution, not fabricated)."""

from __future__ import annotations

import nbformat as nbf

from predictive_maintenance.config import find_project_root


def _nb(cells: list) -> nbf.NotebookNode:
    nb = nbf.v4.new_notebook()
    nb.cells = cells
    nb.metadata.kernelspec = {"display_name": "Python 3", "language": "python", "name": "python3"}
    nb.metadata.language_info = {"name": "python", "version": "3.13"}
    return nb


def _md(text: str):
    return nbf.v4.new_markdown_cell(text)


def _code(text: str):
    return nbf.v4.new_code_cell(text)


COMMON = """from pathlib import Path
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from predictive_maintenance.config import find_project_root
from predictive_maintenance.analysis.eda import load_eda_data
root = find_project_root()
data = load_eda_data(root, 'FD001')
train, test, rul = data['train'], data['test'], data['rul']
print('train', train.shape, 'test', test.shape, 'rul', rul.shape)
"""


def build_notebooks() -> dict[str, nbf.NotebookNode]:
    return {
        "01_dataset_overview.ipynb": _nb(
            [
                _md(
                    "# 01 — Dataset overview\nReproducible FD001 overview. No predictive model is trained."
                ),
                _code(COMMON),
                _code(
                    "from predictive_maintenance.analysis.eda import dataset_overview, engine_lengths, plot_sequence_lengths\noverview = dataset_overview(train, test, rul)\noverview"
                ),
                _code(
                    "lengths = engine_lengths(train, test)\nlengths.groupby('split')['length'].describe()"
                ),
                _code("fig = plot_sequence_lengths(lengths)\nplt.show()"),
                _md(
                    "Training sequences run to failure; test sequences are censored before failure. Engine IDs are local to each split."
                ),
            ]
        ),
        "02_sensor_analysis.ipynb": _nb(
            [
                _md(
                    "# 02 — Sensor analysis\nDistributions, constants, near-constants, and correlations."
                ),
                _code(COMMON),
                _code(
                    "from predictive_maintenance.analysis.eda import sensor_statistics, constant_sensor_report, correlation_matrix, plot_correlation_heatmap\nstats = sensor_statistics(train)\nstats"
                ),
                _code("constant_sensor_report(stats)"),
                _code(
                    "corr = correlation_matrix(train)\nfig = plot_correlation_heatmap(corr)\nplt.show()"
                ),
                _md(
                    "Constant sensors are excluded from initial features; low correlation alone is not a removal criterion."
                ),
            ]
        ),
        "03_degradation_analysis.ipynb": _nb(
            [
                _md(
                    "# 03 — Degradation analysis\nEngine trajectories and early-to-late sensor changes."
                ),
                _code(COMMON),
                _code(
                    "from predictive_maintenance.analysis.eda import degradation_summary, plot_degradation_trajectories, plot_degradation_summary\nsummary, per_engine = degradation_summary(train)\nsummary"
                ),
                _code("fig = plot_degradation_trajectories(train)\nplt.show()"),
                _code("fig = plot_degradation_summary(summary)\nplt.show()"),
                _md(
                    "Systematic early-to-late shifts are consistent with simulated HPC degradation, but are not causal physical diagnosis."
                ),
            ]
        ),
        "04_rul_analysis.ipynb": _nb(
            [
                _md(
                    "# 04 — RUL analysis\nTraining RUL, clipping, lifetimes, and official test terminal RUL."
                ),
                _code(COMMON),
                _code(
                    "from predictive_maintenance.analysis.eda import rul_analysis, plot_rul_distribution, plot_rul_clipping\nresult = rul_analysis(train, test, rul, cap=125)\nresult['stats']"
                ),
                _code("fig = plot_rul_distribution(result)\nplt.show()"),
                _code("fig = plot_rul_clipping(result)\nplt.show()"),
                _md(
                    "Test terminal RUL comes from the separate ground-truth vector; test sequence end is not failure."
                ),
            ]
        ),
    }


def main() -> None:
    root = find_project_root()
    out = root / "notebooks"
    out.mkdir(parents=True, exist_ok=True)
    for name, nb in build_notebooks().items():
        nbf.write(nb, out / name)
        print("Created", out / name)


if __name__ == "__main__":
    main()
